        victim = new Reentrancy_insecure();
        vm.deal(user, initialBalance);

        vm.startPrank(user);
        attacker = new MaliciousContract{value: 1 ether}(address(victim));
        attacker.deposit{value: 1 ether}();
        vm.stopPrank();
